// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    RevertingWinner winner;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint256 bfuzz) public {
        // The fuzzer picks how far ahead the guessed block lies (kept inside the
        // 256-block blockhash window so the answer is well-defined and nonzero).
        uint256 off = bound(bfuzz, 0, 200);

        uint256 target = block.number + 1 + off;

        // Learn the future block's hash (Foundry's blockhash is deterministic
        // for blocks within the window), then rewind to lock it in as a guess.
        vm.roll(target + 1);
        bytes32 h = blockhash(target);
        vm.assume(h != 0);

        // The prize recipient is an adversarial counterparty that REJECTS ether.
        winner = new RevertingWinner(c);
        vm.deal(address(winner), 2 ether);

        // Lock the correct guess at block target - 1, so the target block is `target`.
        vm.roll(target - 1);
        winner.lock{value: 1 ether}(h);

        // Move past the guessed block and settle.
        vm.roll(target + 1);
        bool ok = winner.trySettle();

        // General rule: a winning settle() that cannot deliver the 2-ether prize
        // (recipient reverts on receive) must itself revert — the payout is
        // actually attempted and enforced. The mutant never transfers, so its
        // settle() succeeds silently for the very same input.
        assertTrue(!ok);
    }
}

contract RevertingWinner {
    PredictTheBlockHashChallenge c;
    constructor(PredictTheBlockHashChallenge _c) { c = _c; }

    function lock(bytes32 h) external payable {
        c.lockInGuess{value: msg.value}(h);
    }

    function trySettle() external returns (bool ok) {
        try c.settle() { ok = true; } catch { ok = false; }
    }

    receive() external payable { revert(); }
}
